const GR={
zh:[
["A 是 B: “A is B”","A + 是 + B","是 (shì) links two nouns. It means “is”, “am” or “are”. It does not change for I, you or he.",[["我","wǒ","I"],["是","shì","am"],["学生","xuésheng","student"],["。","",""]],"I am a student."],
["Yes/no questions with 吗","Statement + 吗？","Add 吗 (ma) to the end of a statement. The statement becomes a yes/no question. The word order does not change.",[["你","nǐ","you"],["是","shì","are"],["老师","lǎoshī","teacher"],["吗","ma","(question)"],["？","",""]],"Are you a teacher?"],
["Negation with 不","不 + verb or adjective","Put 不 (bù) directly before a verb or adjective. It means “not” or “do not”.",[["我","wǒ","I"],["不","bù","do not"],["喝","hē","drink"],["茶","chá","tea"],["。","",""]],"I do not drink tea."],
["Possession with 的","A + 的 + B","A 的 B means “A’s B”. Put the owner first, then 的 (de), then the thing.",[["他","tā","he"],["是","shì","is"],["我","wǒ","I"],["的","de","’s"],["朋友","péngyou","friend"],["。","",""]],"He is my friend."],
["Adjectives with 很","Subject + 很 + adjective","Do not use 是 before an adjective. Use 很 (hěn) instead. In this pattern 很 often only links the words and does not mean “very”.",[["学校","xuéxiào","school"],["很","hěn","(link)"],["大","dà","big"],["。","",""]],"The school is big."],
["Counting with 个","Number + 个 + noun","Chinese puts a measure word between a number and a noun. 个 (ge) is the most common measure word.",[["我","wǒ","I"],["有","yǒu","have"],["三","sān","three"],["个","ge","(measure word)"],["朋友","péngyou","friend"],["。","",""]],"I have three friends."],
["Location with 在","Person or thing + 在 + place","在 (zài) means “is at” or “is in” a place.",[["妈妈","māma","mum"],["在","zài","is at"],["家","jiā","home"],["。","",""]],"Mum is at home."],
["Time words before the verb","Subject + time word + verb","Time words such as 今天 (today) and 明天 (tomorrow) go before the verb. They do not go at the end of the sentence.",[["我","wǒ","I"],["明天","míngtiān","tomorrow"],["去","qù","go"],["学校","xuéxiào","school"],["。","",""]],"I go to school tomorrow."],
["Wanting with 想","想 + verb","想 (xiǎng) before a verb means “want to” or “would like to”.",[["我","wǒ","I"],["想","xiǎng","want to"],["去","qù","go"],["中国","Zhōngguó","China"],["。","",""]],"I want to go to China."],
["Completed actions with 了","Verb + 了","了 (le) after a verb shows that the action is complete.",[["他","tā","he"],["来","lái","come"],["了","le","(completed)"],["。","",""]],"He has come."]
],
ja:[
["A は B です: “A is B”","A は B です","は marks the topic. It is written は but pronounced “wa”. です (desu) at the end means “is”.",[["私","watashi","I"],["は","wa","(topic)"],["学生","gakusei","student"],["です","desu","am"],["。","",""]],"I am a student."],
["Questions with か","Sentence + か","Add か (ka) to the end of a sentence. The sentence becomes a question. The word order does not change.",[["あなた","anata","you"],["は","wa","(topic)"],["先生","sensei","teacher"],["です","desu","are"],["か","ka","(question)"],["。","",""]],"Are you a teacher?"],
["Not with じゃないです","A は B じゃないです","じゃないです (ja nai desu) replaces です. It means “is not”.",[["私","watashi","I"],["は","wa","(topic)"],["先生","sensei","teacher"],["じゃないです","ja nai desu","am not"],["。","",""]],"I am not a teacher."],
["Possession with の","A の B","A の B means “A’s B”. Put the owner first, then の (no), then the thing.",[["私","watashi","I"],["の","no","’s"],["友達","tomodachi","friend"],["です","desu","is"],["。","",""]],"This is my friend."],
["Objects with を","Object を verb-ます","を marks the thing that the action is done to. It is written を and pronounced “o”. The ます (masu) ending is the polite present form of a verb.",[["水","mizu","water"],["を","o","(object)"],["飲みます","nomimasu","drink"],["。","",""]],"I drink water."],
["Direction with に","Place に 行きます","に (ni) after a place shows where you go. 行きます (ikimasu) means “go”.",[["学校","gakkou","school"],["に","ni","to"],["行きます","ikimasu","go"],["。","",""]],"I go to school."],
["Past with ました","Verb-ました","Change ます to ました (mashita). The action then happened in the past.",[["昨日","kinou","yesterday"],["、","",""],["水","mizu","water"],["を","o","(object)"],["飲みました","nomimashita","drank"],["。","",""]],"Yesterday I drank water."],
["Negative with ません","Verb-ません","Change ます to ません (masen). The meaning becomes “do not”.",[["お茶","ocha","tea"],["を","o","(object)"],["飲みません","nomimasen","do not drink"],["。","",""]],"I do not drink tea."],
["Wanting with たいです","Verb stem + たいです","Remove ます and add たいです (tai desu). The meaning becomes “want to do”.",[["日本","nihon","Japan"],["に","ni","to"],["行きたいです","ikitai desu","want to go"],["。","",""]],"I want to go to Japan."],
["There is: あります and います","Place に thing が あります","あります (arimasu) means “there is” for things. います (imasu) is for people and animals. が (ga) marks the thing that exists.",[["店","mise","shop"],["に","ni","at"],["水","mizu","water"],["が","ga","(subject)"],["あります","arimasu","there is"],["。","",""]],"There is water at the shop."]
]};
